package com.asmj.marketplace.controller;

import com.asmj.marketplace.commission.*;
import com.asmj.marketplace.model.*;
import com.asmj.marketplace.order.*;
import com.asmj.marketplace.product.*;
import com.asmj.marketplace.repository.UserAccountRepository;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;

@Controller
public class AdminReportsController {
 private final MarketplaceOrderRepository orders; private final CommissionLedgerRepository ledger; private final UserAccountRepository users; private final ProductRepository products;
 public AdminReportsController(MarketplaceOrderRepository o,CommissionLedgerRepository l,UserAccountRepository u,ProductRepository p){orders=o;ledger=l;users=u;products=p;}
 @GetMapping("/admin/reports") public String reports(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to,Model m){LocalDate end=to==null?LocalDate.now():to;LocalDate start=from==null?end.minusDays(29):from;if(start.isAfter(end)){m.addAttribute("errorMessage","Start date must not be after end date.");start=end.minusDays(29);}LocalDate reportStart=start;List<MarketplaceOrder> range=rangeOrders(reportStart,end);List<MarketplaceOrder> paid=range.stream().filter(o->o.getPaymentStatus()==PaymentStatus.VERIFIED).toList();BigDecimal sales=paid.stream().filter(o->o.getStatus()==OrderStatus.COMPLETED).map(MarketplaceOrder::getTotal).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);List<CommissionLedger> ledgers=ledger.findAllByOrderByWeekStartDesc().stream().filter(x->x.getWeekStart()!=null&&!x.getWeekStart().isBefore(reportStart)&&!x.getWeekStart().isAfter(end)).toList();BigDecimal collected=ledgers.stream().filter(x->"PAID".equalsIgnoreCase(x.getStatus())).map(CommissionLedger::getCommissionAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal outstanding=ledgers.stream().filter(x->!"PAID".equalsIgnoreCase(x.getStatus())).map(CommissionLedger::getCommissionAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,BigDecimal> vendorSales=new TreeMap<>();Map<String,Long> topProducts=new HashMap<>();for(MarketplaceOrder o:paid)if(o.getStatus()==OrderStatus.COMPLETED){vendorSales.merge(o.getVendorName()==null?"Vendor":o.getVendorName(),o.getTotal()==null?BigDecimal.ZERO:o.getTotal(),BigDecimal::add);if(o.getItems()!=null)for(OrderItem item:o.getItems())topProducts.merge(item.getProductName()==null?"Product":item.getProductName(),(long)Math.max(0,item.getQuantity()),Long::sum);}m.addAttribute("from",start);m.addAttribute("to",end);m.addAttribute("ordersCount",range.size());m.addAttribute("paidOrdersCount",paid.size());m.addAttribute("completedSales",sales);m.addAttribute("collectedCommission",collected);m.addAttribute("outstandingCommission",outstanding);m.addAttribute("customerCount",users.countByRoleAndVendorStatus(Role.ROLE_CUSTOMER,VendorStatus.NOT_APPLICABLE));m.addAttribute("vendorCount",users.countByRoleAndVendorStatus(Role.ROLE_VENDOR,VendorStatus.APPROVED));m.addAttribute("productCount",products.count());m.addAttribute("vendorSales",vendorSales);m.addAttribute("topProducts",topProducts.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(10).toList());return "admin/reports";}
 @GetMapping("/admin/reports/export.csv") public void export(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to,HttpServletResponse response)throws IOException{if(from.isAfter(to)||Duration.between(from.atStartOfDay(),to.plusDays(1).atStartOfDay()).toDays()>3660){response.sendError(400,"Invalid report date range");return;}response.setContentType("text/csv;charset=UTF-8");response.setHeader("Content-Disposition","attachment; filename=asmj-marketplace-orders.csv");response.getOutputStream().write(new byte[]{(byte)0xEF,(byte)0xBB,(byte)0xBF});StringBuilder b=new StringBuilder("Order Number,Created At,Customer,Vendor,Status,Payment Method,Payment Status,Subtotal,Discount,Coupon,Delivery,Total\r\n");for(MarketplaceOrder o:rangeOrders(from,to)){b.append(csv(o.getOrderNumber())).append(',').append(csv(String.valueOf(o.getCreatedAt()))).append(',').append(csv(o.getCustomerName())).append(',').append(csv(o.getVendorName())).append(',').append(csv(String.valueOf(o.getStatus()))).append(',').append(csv(String.valueOf(o.getPaymentMethod()))).append(',').append(csv(String.valueOf(o.getPaymentStatus()))).append(',').append(csv(String.valueOf(o.getSubtotal()))).append(',').append(csv(String.valueOf(o.getDiscountAmount()))).append(',').append(csv(o.getCouponCode())).append(',').append(csv(String.valueOf(o.getDeliveryCharge()))).append(',').append(csv(String.valueOf(o.getTotal()))).append("\r\n");}response.getOutputStream().write(b.toString().getBytes(StandardCharsets.UTF_8));}
 private List<MarketplaceOrder> rangeOrders(LocalDate from,LocalDate to){Instant a=from.atStartOfDay(ZoneId.systemDefault()).toInstant(),b=to.plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant();return orders.findAllByOrderByCreatedAtDesc().stream().filter(o->o.getCreatedAt()!=null&&!o.getCreatedAt().isBefore(a)&&o.getCreatedAt().isBefore(b)).toList();}
 private String csv(String s){if(s==null)return "\"\"";String safe=s.matches("^[\\s]*[=+@-].*")?"\'"+s:s;return "\""+safe.replace("\"","\"\"")+"\"";}
}
